// CRM-лиды и таблица анализа WF2 читаются по имени ноды;
// нода "Wait for CRM + Sheets" гарантирует, что обе ветки уже выполнены.
const rawLeads = $('Get leads from Zoho CRM').all();
const sheetRows = $('Get WF2 analysis from Sheets').all()
  .map(i => i.json || {})
  .filter(r => String(r.session_id ?? '').trim() !== '');

// Анализ WF2 по session_id (= Skype_ID в Zoho).
const analysisBySession = {};
for (const row of sheetRows) {
  const sid = String(row.session_id).trim();
  const text = String(row.analysis ?? '').trim();
  if (text) analysisBySession[sid] = text;
}

// Отчётный период: последние 7 дней.
const periodStart = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

const pick = (...values) =>
  values.find(v =>
    v !== undefined &&
    v !== null &&
    String(v).trim() !== ''
  );

const normalize = v => String(v ?? '').trim();

const isUnknown = v =>
  !normalize(v) ||
  [
    'не определен',
    'не определён',
    'не визначений',
    'не визначено',
    'не вказано',
    'не указано',
    'unknown',
    'n/a',
    'null'
  ].includes(normalize(v).toLowerCase());

// Формируем записи и оставляем только лиды
// с заполненным Skype_ID — session_id.
const leads = rawLeads.map(item => {
  const r = item.json || {};

  let payload = {};
  const desc = r.Description ?? r.description ?? '';

  if (typeof desc === 'string' && desc.trim()) {
    try {
      payload = JSON.parse(desc);
    } catch (_) {}
  } else if (desc && typeof desc === 'object') {
    payload = desc;
  }

  const sessionId = pick(
    r.Skype_ID,
    r.SkypeId,
    r.skype_id,
    ''
  );

  const scoreRaw = pick(
    payload.score,
    r.Score,
    r.score,
    ''
  );

  const scoreNum =
    scoreRaw === '' ? NaN : Number(scoreRaw);

  const score =
    Number.isFinite(scoreNum) &&
    scoreNum >= 0 &&
    scoreNum <= 10
      ? scoreNum
      : '';

  const statusRaw = pick(
    payload.status,
    r.Status,
    r.status,
    ''
  );

  const status = score !== ''
    ? (
        score <= 3
          ? 'Disqualified'
          : score <= 7
            ? 'In Progress'
            : 'Qualified'
      )
    : 'Undetermined';

  return {
    lead_id: !isUnknown(sessionId)
      ? 'GL-' + String(sessionId).trim()
      : pick(payload.lead_id, r.Lead_ID, r.lead_id, r.id, ''),
    session_id: sessionId,
    name: pick(
      payload.name,
      r.Full_Name,
      [r.First_Name, r.Last_Name]
        .filter(Boolean)
        .join(' '),
      r.Last_Name,
      'Не вказано'
    ),
    need: pick(
      payload.need,
      r.Need,
      r.need,
      'Не визначено'
    ),
    budget: pick(
      payload.budget,
      r.Budget,
      r.budget,
      'Не визначений'
    ),
    authority: pick(
      payload.authority,
      r.Authority,
      r.authority,
      'Не визначено'
    ),
    timeline: pick(
      payload.timeline,
      r.Timeline,
      r.timeline,
      'Не визначено'
    ),
    score,
    status,
    analysis: pick(
      analysisBySession[String(sessionId ?? '').trim()],
      payload.analysis,
      r.Analysis,
      r.analysis,
      ''
    ),
    analysis_source: analysisBySession[String(sessionId ?? '').trim()]
      ? 'WF2 (Google Sheets)'
      : 'Zoho/WF1',
    created_time: pick(r.Created_Time, r.createdTime, r.CreatedTime, '')
  };
}).filter(lead => !isUnknown(lead.session_id));

// Статистика только по обработанным лидам.
const total = leads.length;

const qualified = leads.filter(
  l => l.status === 'Qualified'
).length;

const inProgress = leads.filter(
  l => l.status === 'In Progress'
).length;

const undetermined = leads.filter(
  l => l.status === 'Undetermined'
).length;

// Новые лиды — по времени создания в отчётном периоде.
const newLeads = leads.filter(l => {
  if (!l.created_time) return false;
  const t = new Date(l.created_time);
  return !isNaN(t) && t >= periodStart;
}).length;

const analyzedByWf2 = leads.filter(
  l => l.analysis_source === 'WF2 (Google Sheets)'
).length;

const disqualified = leads.filter(
  l => l.status === 'Disqualified'
).length;

const scores = leads
  .map(l => l.score)
  .filter(score => score !== '');

const averageScore = scores.length
  ? Number((
      scores.reduce((a, b) => a + b, 0) /
      scores.length
    ).toFixed(1))
  : 0;

const budgets = leads.filter(
  l => !isUnknown(l.budget)
);

const budgetsDefined = budgets.length;
const budgetsUnknown = total - budgetsDefined;

const byStage = {
  Qualified: qualified,
  'In Progress': inProgress,
  Disqualified: disqualified,
  Undetermined: undetermined
};

return [{
  json: {
    total_leads: total,
    crm_total_received: rawLeads.length,
    analyzed_leads: total,
    leads_without_session_id:
      rawLeads.length - total,
    new_leads_count: newLeads,
    new_leads_period_days: 7,
    undetermined,
    leads_with_wf2_analysis: analyzedByWf2,
    sheet_rows_received: sheetRows.length,
    qualified,
    in_progress: inProgress,
    disqualified,
    average_score: averageScore,
    scores_count: scores.length,
    budgets_defined: budgetsDefined,
    budgets_unknown: budgetsUnknown,
    by_stage: byStage,
    by_owner: {
      'Не використовується — поле owner відсутнє': total
    },
    leads
  }
}];

